CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, passwordHash TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE sessions (tokenHash TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expiresAt INTEGER NOT NULL, lastSeen INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE provider_connections (id TEXT PRIMARY KEY, type TEXT NOT NULL, label TEXT NOT NULL, encryptedSecret TEXT NOT NULL, encryptionVersion INTEGER NOT NULL DEFAULT 1, config TEXT NOT NULL, lastValidated INTEGER, validationState TEXT NOT NULL DEFAULT 'Unknown');
CREATE TABLE applications (id TEXT PRIMARY KEY, name TEXT NOT NULL, publicHostname TEXT NOT NULL UNIQUE, desiredRelease TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0, activeOriginId TEXT REFERENCES origins(id), operationalState TEXT NOT NULL DEFAULT 'PAUSED', automationEnabled INTEGER NOT NULL DEFAULT 0, configurationRevision INTEGER NOT NULL DEFAULT 1, createdAt INTEGER NOT NULL);
CREATE TABLE origins (id TEXT PRIMARY KEY, applicationId TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('primary','backup')), providerConnectionId TEXT REFERENCES provider_connections(id), config TEXT NOT NULL, observation TEXT, power TEXT NOT NULL DEFAULT 'unknown', healthySince INTEGER, UNIQUE(applicationId,role));
CREATE TABLE routing_configs (applicationId TEXT PRIMARY KEY REFERENCES applications(id) ON DELETE CASCADE, providerConnectionId TEXT REFERENCES provider_connections(id), config TEXT NOT NULL);
CREATE TABLE failover_policies (applicationId TEXT PRIMARY KEY REFERENCES applications(id) ON DELETE CASCADE, config TEXT NOT NULL);
CREATE TABLE probe_results (id INTEGER PRIMARY KEY AUTOINCREMENT, originId TEXT NOT NULL REFERENCES origins(id) ON DELETE CASCADE, timestamp INTEGER NOT NULL, success INTEGER NOT NULL, latency REAL NOT NULL, data TEXT NOT NULL);
CREATE INDEX probe_origin_time ON probe_results(originId,timestamp);
CREATE TABLE probe_aggregates (originId TEXT NOT NULL REFERENCES origins(id) ON DELETE CASCADE, bucket INTEGER NOT NULL, count INTEGER NOT NULL, successes INTEGER NOT NULL, latencySum REAL NOT NULL, PRIMARY KEY(originId,bucket));
CREATE TABLE incidents (id TEXT PRIMARY KEY, applicationId TEXT NOT NULL REFERENCES applications(id), trigger TEXT NOT NULL, actor TEXT NOT NULL, phase TEXT NOT NULL, outcome TEXT, targetOriginId TEXT NOT NULL REFERENCES origins(id), previousOriginId TEXT REFERENCES origins(id), startedAt INTEGER NOT NULL, deadlineAt INTEGER NOT NULL, bootDeadlineAt INTEGER NOT NULL, completedAt INTEGER, objectiveMet INTEGER, correlationId TEXT NOT NULL, error TEXT, cancelRequested INTEGER NOT NULL DEFAULT 0, snapshot TEXT NOT NULL, readinessCount INTEGER NOT NULL DEFAULT 0, nextAttemptAt INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_active_incident ON incidents(applicationId) WHERE outcome IS NULL;
CREATE INDEX incidents_time ON incidents(startedAt);
CREATE TABLE incident_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, incidentId TEXT NOT NULL REFERENCES incidents(id), sequence INTEGER NOT NULL, phase TEXT NOT NULL, action TEXT NOT NULL, intent TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 1, startedAt INTEGER NOT NULL, completedAt INTEGER, result TEXT NOT NULL, error TEXT, UNIQUE(incidentId,sequence));
CREATE TABLE operation_leases (applicationId TEXT PRIMARY KEY REFERENCES applications(id), ownerId TEXT NOT NULL, generation INTEGER NOT NULL, expiresAt INTEGER NOT NULL);
CREATE TABLE idempotency_keys (key TEXT PRIMARY KEY, requestHash TEXT NOT NULL, operationId TEXT NOT NULL REFERENCES incidents(id), createdAt INTEGER NOT NULL);
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, diff TEXT NOT NULL, timestamp INTEGER NOT NULL, correlationId TEXT NOT NULL);
CREATE INDEX audit_time ON audit_events(timestamp);
CREATE TABLE notification_outbox (id TEXT PRIMARY KEY, event TEXT NOT NULL, destination TEXT NOT NULL, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, nextAttemptAt INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE controller_guard (id INTEGER PRIMARY KEY CHECK(id=1), ownerId TEXT NOT NULL, expiresAt INTEGER NOT NULL);
CREATE TABLE demo_resources (id TEXT PRIMARY KEY REFERENCES origins(id) ON DELETE CASCADE, healthy INTEGER NOT NULL DEFAULT 1, running INTEGER NOT NULL DEFAULT 1, dependencies INTEGER NOT NULL DEFAULT 1, starts INTEGER NOT NULL DEFAULT 0, identityOverride TEXT);
CREATE TABLE demo_routes (applicationId TEXT PRIMARY KEY REFERENCES applications(id), records TEXT NOT NULL, writes INTEGER NOT NULL DEFAULT 0);
